// === Tab: mySketch.js ===
const PIXEL_DENSITY = 1;

let theShader;
let canvas;
let f;
let textGraphic;
let frame = 0;

let control = {
	fps: 60,
	pixelSize: 1,
	alternativeRule: false,
	showText: true,
	showOuterRing: true,
	showCursorRing: true,
	clear: clearCanvas
}

window.onload = function() {
	var gui = new dat.GUI();
	gui.domElement.id = 'gui';
	gui.add(control, 'fps', 1, 60, 1).name("Iteration FPS");
	gui.add(control, 'pixelSize', 1, 10, 1).name("Pixel Size");
	gui.add(control, 'alternativeRule').name("Use Alternative Rule");
	gui.add(control, 'showText').name("Show Text");
	gui.add(control, 'showOuterRing').name("Show Outer Ring");
	gui.add(control, 'showCursorRing').name("Show Cursor Ring");
	gui.add(control, 'clear').name("Clear");
};


function preload() {
	theShader = loadShader('https://openprocessing.org/sketch/1834477/files/vert.glsl', 'frag.glsl');
	f = loadFont(
    "https://cdnjs.cloudflare.com/ajax/libs/topcoat/0.8.0/font/SourceCodePro-Bold.otf"
  );
}

function setup() {
	pixelDensity(PIXEL_DENSITY);
	canvas = createCanvas(1000, 1000, WEBGL);
	background(0);
	noStroke();

	shader(theShader);
	theShader.setUniform('u_canvas', canvas);

	textGraphic = createGraphics(1000, 1000, WEBGL);
	textGraphic.pixelDensity(PIXEL_DENSITY);
	textGraphic.background(0);
	textGraphic.textFont(f);
	textGraphic.textSize(70);
	textGraphic.textAlign(CENTER, CENTER);
	textGraphic.fill("#ffffff");
	textGraphic.text("# Game  ", 0, -80);
	textGraphic.text("  of    ", 0, -10);
	textGraphic.text("  Life #", 0, 60);
	theShader.setUniform("u_text", textGraphic);
}

function draw() {
	var y = ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))-500) / min(1, windowWidth / windowHeight) + 500;

	theShader.setUniform("u_resolution", [width * PIXEL_DENSITY, height * PIXEL_DENSITY]);
	theShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) * PIXEL_DENSITY, (height-y) * PIXEL_DENSITY]);
	theShader.setUniform("u_frame", frame++);
	theShader.setUniform("u_fps", control.fps);
	theShader.setUniform("u_pixel_size", control.pixelSize);
	theShader.setUniform("u_alternative_rule", control.alternativeRule);
	theShader.setUniform("u_show_text", control.showText);
	theShader.setUniform("u_show_outer_ring", control.showOuterRing);
	theShader.setUniform("u_show_cursor_ring", control.showCursorRing);

	rect(width * -0.5, height * -0.5, width, height);
}

function clearCanvas() {
	background(0);
}


// === Tab: frag.glsl ===
#define PI 3.14159265359
#define EPSILON 0.0001
#define S(a,b) smoothstep(a-EPSILON,a,b)

#ifdef GL_ES
precision mediump float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform sampler2D u_canvas;
uniform sampler2D u_text;
uniform float u_frame;
uniform float u_fps;
uniform float u_pixel_size;
uniform bool u_alternative_rule;
uniform bool u_show_text;
uniform bool u_show_outer_ring;
uniform bool u_show_cursor_ring;

int is_cell_alive(vec2 uv) {
	uv = fract(uv);
	float r = texture2D(u_canvas, uv).r;
	r = S(.2, r);
	return int(r);
}

void main() {
	float c = 0.;
	vec3 col = vec3(0.);
	vec2 uv = gl_FragCoord.xy / u_resolution.xy;	
	vec2 mouse = uv*u_mouse / gl_FragCoord.xy;

	float cell_count = 1000. / u_pixel_size;

	vec2 gv = fract(uv * cell_count);
	vec2 id = floor(uv * cell_count) + vec2(.5);
	id /= cell_count;

	vec2 mouse_id = floor(cell_count * mouse) + vec2(.5);
	mouse_id /= cell_count;

	vec2 canvas_uv = id;
	canvas_uv.y = 1. - canvas_uv.y;

	vec2 r = vec2(1./cell_count, 0.);
	vec2 t = vec2(0., 1./cell_count);
	int neighbor = 
		is_cell_alive(canvas_uv + t - r) +
		is_cell_alive(canvas_uv + t    ) +
		is_cell_alive(canvas_uv + t + r) +
		is_cell_alive(canvas_uv     - r) +
		is_cell_alive(canvas_uv     + r) +
		is_cell_alive(canvas_uv - t - r) +
		is_cell_alive(canvas_uv - t    ) +
		is_cell_alive(canvas_uv - t + r);

	int is_alive = 0;
	int was_alive = is_cell_alive(canvas_uv);

	int amount_to_rebirth = 3;
	if(u_alternative_rule) {
		amount_to_rebirth = 1;
	}

	if (neighbor == amount_to_rebirth) {
		is_alive = 1;
	} else if(neighbor == 2) {
		is_alive = was_alive;
	} else {
		is_alive = 0;
	}

	c = float(is_alive);

	float need_refresh = S(60./u_fps - 1., mod(u_frame, 60./u_fps));
	c = mix(float(was_alive), c, need_refresh);

	float deco = 0.;
	float border_width = .001 * u_pixel_size;

	float mouse_cir = distance(id, mouse_id);
	float mouse_cir_r = .031;
	float mouse_cir_line = floor( 
		S(mouse_cir, mouse_cir_r) * 
		S(mouse_cir_r - border_width, mouse_cir)
	);

	float outer_cir = distance(id, vec2(.5));
	float outer_cir_r = .43 + cos(2. * u_frame/60.) * .05;
	float outer_cir_line = floor( 
		S(outer_cir, outer_cir_r) * 
		S(outer_cir_r - border_width, outer_cir)
	);

	vec2 text_uv = id;
	text_uv.y = 1. - text_uv.y;
	float text = texture2D(u_text, text_uv).r;
	text = S(.2, text);

	if(u_show_text) {
		deco = max(deco, text);
	}
	if(u_show_outer_ring) {
		deco = max(deco, outer_cir_line);
	}
	if(u_show_cursor_ring) {
		deco = max(deco, mouse_cir_line);
	}

	vec3 color1 = vec3(.11, .06, .27);
	vec3 color2 = vec3(.96, .31, .22);
	vec3 color3 = vec3(1., .92, .98);

	col = mix(color1, color2, c);
	col = mix(col, color3, deco);

  gl_FragColor = vec4(col, 1.); 
}

// === Tab: vert.glsl ===
 attribute vec3 aPosition;
 attribute vec2 aTexCoord;
 uniform mat4 uProjectionMatrix;
 uniform mat4 uModelViewMatrix;
 varying vec2 vTexCoord;

 void main() {
	 vTexCoord = aTexCoord;
	 vec4 position = vec4(aPosition, 1.0);
	 gl_Position = uProjectionMatrix * uModelViewMatrix * position;
 }

